// Command gen generates the typed Flashduty service layer and models from the
// vendored OpenAPI specification (openapi/openapi.en.json).
//
// It is a maintainer tool: run `go generate ./...` (or `go run ./internal/cmd/gen`)
// from the repository root after refreshing the vendored spec. Generated files
// carry a DO NOT EDIT header and are committed to the repository.
package main

import (
	"encoding/json"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const genHeader = "// Code generated by internal/cmd/gen; DO NOT EDIT.\n\n"

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "gen:", err)
		os.Exit(1)
	}
}

// Gen holds parsed spec state and accumulated output.
type Gen struct {
	root    string
	schemas map[string]any // name -> schema map

	emptyTypes map[string]bool // schema names that resolve to an empty object
	skip       map[string]bool // schema names handled by hand / infra

	structQueue []string        // schema/synth names pending struct emission
	queued      map[string]bool // names already queued/emitted
	synth       map[string]any  // synthesized nested schemas (name -> schema map)

	getRequests []getRequest // synthesized GET query-param request structs

	looseCount int // count of loose object/any fallbacks (R6 tracking)
}

type service struct {
	Name string // Go service type prefix, e.g. "Incidents"
	Tag  string
	Ops  []op
}

type op struct {
	Method string // Go method name
	HTTP   string // HTTP verb: "POST" or "GET"
	Path   string
	Doc    []string
	ReqGo  string // request Go type ("" => no body)
	DataGo string // response data Go type ("" => no typed data)
}

// queryParam is one GET query parameter, projected onto a Go struct field.
type queryParam struct {
	Wire     string // query parameter name
	GoField  string // Go field name
	GoType   string // Go type
	Required bool
	Doc      string
}

// getRequest is a synthesized request struct for a GET operation; its fields
// carry `url` tags consumed by the runtime query encoder (query.go).
type getRequest struct {
	Name   string
	Doc    string
	Params []queryParam
}

func run() error {
	root, err := repoRoot()
	if err != nil {
		return err
	}
	spec, err := loadSpec(filepath.Join(root, "openapi", "openapi.en.json"))
	if err != nil {
		return err
	}

	g := &Gen{
		root:       root,
		schemas:    asMap(asMap(spec["components"])["schemas"]),
		emptyTypes: map[string]bool{},
		skip:       map[string]bool{"SuccessEnvelope": true, "ErrorResponse": true, "DutyError": true},
		queued:     map[string]bool{},
		synth:      map[string]any{},
	}
	g.detectEmpty()

	services := g.collectServices(asMap(spec["paths"]))

	// Emit models first so type resolution can synthesize nested types, then
	// services, then the wiring.
	modelsSrc := g.emitModels()
	servicesSrc := map[string]string{}
	for _, s := range services {
		servicesSrc[s.Name] = g.emitService(s)
	}
	wiringSrc := g.emitWiring(services)

	// Write files.
	if err := writeGo(filepath.Join(root, "models_gen.go"), modelsSrc); err != nil {
		return err
	}
	if err := writeGo(filepath.Join(root, "services_gen.go"), wiringSrc); err != nil {
		return err
	}
	for name, src := range servicesSrc {
		if err := writeGo(filepath.Join(root, fileName(name)+".go"), src); err != nil {
			return err
		}
	}

	fmt.Printf("gen: %d services, %d operations, %d schemas, %d loose fields\n",
		len(services), countOps(services), len(g.schemas), g.looseCount)
	return nil
}

func countOps(svcs []service) int {
	n := 0
	for _, s := range svcs {
		n += len(s.Ops)
	}
	return n
}

// ---- services -------------------------------------------------------------

type opEntry struct {
	path   string
	method string // upper-case HTTP verb
	op     map[string]any
}

func (g *Gen) collectServices(paths map[string]any) []service {
	byTag := map[string][]opEntry{}
	for p, item := range paths {
		for method, raw := range asMap(item) {
			m := strings.ToUpper(method)
			if m != "POST" && m != "GET" {
				continue
			}
			o := asMap(raw)
			tags := asSlice(o["tags"])
			if len(tags) == 0 {
				continue
			}
			tag, _ := tags[0].(string)
			byTag[tag] = append(byTag[tag], opEntry{p, m, o})
		}
	}

	var tagNames []string
	for t := range byTag {
		tagNames = append(tagNames, t)
	}
	sort.Strings(tagNames)

	var services []service
	for _, tag := range tagNames {
		entries := byTag[tag]
		sort.Slice(entries, func(i, j int) bool {
			return str(entries[i].op, "operationId") < str(entries[j].op, "operationId")
		})
		var opIDs []string
		for _, e := range entries {
			opIDs = append(opIDs, str(e.op, "operationId"))
		}
		names := methodNames(opIDs)

		svc := service{Name: serviceName(tag), Tag: tag}
		for _, e := range entries {
			o := e.op
			hint := svc.Name + names[str(o, "operationId")]
			var reqGo string
			if e.method == "GET" {
				reqGo = g.getRequestType(o, hint)
			} else {
				reqGo = g.requestType(o, hint)
			}
			svc.Ops = append(svc.Ops, op{
				Method: names[str(o, "operationId")],
				HTTP:   e.method,
				Path:   e.path,
				Doc:    g.opDoc(o, e.method, e.path),
				ReqGo:  reqGo,
				DataGo: g.dataType(o, hint),
			})
		}
		services = append(services, svc)
	}
	return services
}

// getRequestType synthesizes a request struct from a GET op's query parameters
// and records it for emission. Returns "" when the op has no query parameters.
func (g *Gen) getRequestType(o map[string]any, hint string) string {
	var params []queryParam
	used := map[string]bool{}
	for _, raw := range asSlice(o["parameters"]) {
		pm := asMap(raw)
		if str(pm, "in") != "query" {
			continue // path params would need templating; none exist in the spec
		}
		wire := str(pm, "name")
		if wire == "" {
			continue
		}
		field := goName(wire)
		if field == "" {
			field = "Param"
		}
		for used[field] {
			field += "_"
		}
		used[field] = true
		req, _ := pm["required"].(bool)
		params = append(params, queryParam{
			Wire:     wire,
			GoField:  field,
			GoType:   g.goTypeOf(asMap(pm["schema"]), hint+field),
			Required: req,
			Doc:      str(pm, "description"),
		})
	}
	if len(params) == 0 {
		return ""
	}
	name := hint + "Request"
	g.getRequests = append(g.getRequests, getRequest{
		Name:   name,
		Doc:    str(o, "summary"),
		Params: params,
	})
	return name
}

func (g *Gen) opDoc(o map[string]any, method, path string) []string {
	var lines []string
	summary := str(o, "summary")
	if summary != "" {
		lines = append(lines, summary+".")
	}
	if d := str(o, "description"); d != "" && d != summary {
		lines = append(lines, "")
		lines = append(lines, wrapText(d)...)
	}
	lines = append(lines, "")
	lines = append(lines, fmt.Sprintf("API: %s %s (%s).", method, path, str(o, "operationId")))
	return lines
}

// requestType resolves the request body Go type. Returns "" when the body is
// absent or an empty object (method takes no body parameter).
func (g *Gen) requestType(o map[string]any, hint string) string {
	sch := schemaOf(asMap(o["requestBody"]))
	if sch == nil {
		return ""
	}
	if ref := refName(sch); ref != "" {
		if g.emptyTypes[ref] {
			return ""
		}
		return goName(ref)
	}
	// inline body
	if isEmptyObject(sch) {
		return ""
	}
	return g.goTypeOf(sch, hint+"Request")
}

// dataType resolves the response data Go type from the 200 envelope. Returns ""
// when there is no data or it is an empty object.
func (g *Gen) dataType(o map[string]any, hint string) string {
	resp := asMap(asMap(o["responses"])["200"])
	sch := schemaOf(resp)
	if sch == nil {
		return ""
	}
	var data map[string]any
	if allOf := asSlice(sch["allOf"]); len(allOf) > 0 {
		for _, part := range allOf {
			pm := asMap(part)
			if props := asMap(pm["properties"]); props != nil {
				if d, ok := props["data"]; ok {
					data = asMap(d)
				}
			}
		}
	} else if refName(sch) != "" {
		data = sch
	}
	if data == nil {
		return ""
	}
	if ref := refName(data); ref != "" {
		if g.emptyTypes[ref] {
			return ""
		}
		return goName(ref)
	}
	if isEmptyObject(data) {
		return ""
	}
	return g.goTypeOf(data, hint+"Response")
}

// ---- model emission -------------------------------------------------------

func (g *Gen) detectEmpty() {
	for name := range g.schemas {
		if g.skip[name] {
			continue
		}
		if isEmptyObject(g.resolveObject(name)) {
			g.emptyTypes[name] = true
		}
	}
}

// resolveObject merges allOf parts of a named schema into a single object map.
func (g *Gen) resolveObject(name string) map[string]any {
	s := asMap(g.schemas[name])
	return g.mergeAllOf(s)
}

func (g *Gen) mergeAllOf(s map[string]any) map[string]any {
	if s == nil {
		return nil
	}
	allOf := asSlice(s["allOf"])
	if len(allOf) == 0 {
		return s
	}
	merged := map[string]any{"type": "object"}
	props := map[string]any{}
	for _, part := range allOf {
		pm := asMap(part)
		if ref := refName(pm); ref != "" {
			pm = g.resolveObject(ref)
		}
		for k, v := range asMap(pm["properties"]) {
			props[k] = v
		}
	}
	// include this schema's own properties too
	for k, v := range asMap(s["properties"]) {
		props[k] = v
	}
	merged["properties"] = props
	return merged
}

func (g *Gen) emitModels() string {
	var b strings.Builder
	b.WriteString(genHeader)
	b.WriteString("package flashduty\n\n")

	names := make([]string, 0, len(g.schemas))
	for n := range g.schemas {
		names = append(names, n)
	}
	sort.Strings(names)

	// First pass: enums and aliases, queue structs.
	var enumsAndAliases strings.Builder
	for _, name := range names {
		if g.skip[name] {
			continue
		}
		s := asMap(g.schemas[name])
		switch {
		case s["enum"] != nil && typeStr(s) == "string":
			enumsAndAliases.WriteString(g.emitEnum(goName(name), s))
		case typeStr(s) == "array":
			elem := g.goTypeOf(asMap(s["items"]), goName(name)+"Item")
			enumsAndAliases.WriteString(fmt.Sprintf("// %s is a list response payload.\ntype %s []%s\n\n", goName(name), goName(name), elem))
		case typeStr(s) == "string", typeStr(s) == "integer", typeStr(s) == "number", typeStr(s) == "boolean":
			enumsAndAliases.WriteString(fmt.Sprintf("type %s %s\n\n", goName(name), g.goTypeOf(s, goName(name))))
		default:
			g.queue(goName(name), g.mergeAllOf(s))
		}
	}

	// Drain the struct worklist (synthesized nested types append as discovered).
	var structs strings.Builder
	for len(g.structQueue) > 0 {
		n := g.structQueue[0]
		g.structQueue = g.structQueue[1:]
		schema := asMap(g.synth[n])
		structs.WriteString(g.emitStruct(n, schema))
	}

	b.WriteString(enumsAndAliases.String())
	b.WriteString(structs.String())
	b.WriteString(g.emitGetRequests())
	return b.String()
}

// emitGetRequests renders the synthesized GET query-param request structs.
// Their fields carry `url` tags (omitempty for optional parameters) consumed by
// the runtime query encoder.
func (g *Gen) emitGetRequests() string {
	if len(g.getRequests) == 0 {
		return ""
	}
	reqs := append([]getRequest(nil), g.getRequests...)
	sort.Slice(reqs, func(i, j int) bool { return reqs[i].Name < reqs[j].Name })

	var b strings.Builder
	for _, r := range reqs {
		if r.Doc != "" {
			b.WriteString(fmt.Sprintf("// %s holds the query parameters for %s.\n", r.Name, strings.TrimSuffix(r.Doc, ".")))
		} else {
			b.WriteString(fmt.Sprintf("// %s holds the query parameters for the request.\n", r.Name))
		}
		b.WriteString(fmt.Sprintf("type %s struct {\n", r.Name))
		for _, p := range r.Params {
			if p.Doc != "" {
				for _, l := range wrapText(p.Doc) {
					b.WriteString("\t// " + l + "\n")
				}
			}
			tag := p.Wire
			if !p.Required {
				tag += ",omitempty"
			}
			b.WriteString(fmt.Sprintf("\t%s %s `url:%q`\n", p.GoField, p.GoType, tag))
		}
		b.WriteString("}\n\n")
	}
	return b.String()
}

func (g *Gen) queue(name string, schema map[string]any) string {
	if g.queued[name] {
		return name
	}
	g.queued[name] = true
	g.synth[name] = schema
	g.structQueue = append(g.structQueue, name)
	return name
}

func (g *Gen) emitEnum(name string, s map[string]any) string {
	var b strings.Builder
	if d := str(s, "description"); d != "" {
		for _, l := range wrapText(d) {
			b.WriteString("// " + name + " " + strings.TrimPrefix(l, "") + "\n")
			break
		}
	}
	b.WriteString(fmt.Sprintf("type %s string\n\nconst (\n", name))
	for _, v := range asSlice(s["enum"]) {
		val, _ := v.(string)
		if val == "" {
			continue
		}
		b.WriteString(fmt.Sprintf("\t%s%s %s = %q\n", name, goName(val), name, val))
	}
	b.WriteString(")\n\n")
	return b.String()
}

func (g *Gen) emitStruct(name string, s map[string]any) string {
	var b strings.Builder
	b.WriteString(fmt.Sprintf("// %s is generated from the Flashduty OpenAPI schema.\n", name))
	props := asMap(s["properties"])
	if len(props) == 0 {
		b.WriteString(fmt.Sprintf("type %s struct{}\n\n", name))
		return b.String()
	}
	// Collapse the pagination input trio (p + limit [+ search_after_ctx]) into an
	// embedded ListOptions, the shared go-github-style pagination type. Only
	// applies to JSON body structs; GET query structs keep inline url-tagged
	// fields (emitGetRequests). Detection requires both p and limit as integers.
	paginated := isIntProp(props["p"]) && isIntProp(props["limit"])
	skipPagination := map[string]bool{}
	if paginated {
		skipPagination["p"] = true
		skipPagination["limit"] = true
		skipPagination["search_after_ctx"] = true
	}

	keys := make([]string, 0, len(props))
	for k := range props {
		if skipPagination[k] {
			continue
		}
		keys = append(keys, k)
	}
	sort.Strings(keys)

	b.WriteString(fmt.Sprintf("type %s struct {\n", name))
	usedField := map[string]bool{}
	if paginated {
		b.WriteString("\tListOptions\n")
	}
	for _, k := range keys {
		pv := asMap(props[k])
		field := goName(k)
		if field == "" || field == name {
			field = field + "Field"
		}
		for usedField[field] {
			field += "_"
		}
		usedField[field] = true
		gt := g.goTypeOf(pv, name+field)
		if gt == "map[string]any" || gt == "any" {
			g.looseCount++
		}
		if d := str(pv, "description"); d != "" {
			for _, l := range wrapText(d) {
				b.WriteString("\t// " + l + "\n")
			}
		}
		b.WriteString(fmt.Sprintf("\t%s %s `json:%q`\n", field, gt, k+",omitempty"))
	}
	b.WriteString("}\n\n")
	return b.String()
}

// goTypeOf resolves a schema map to a Go type string, synthesizing nested
// struct types (queued for emission) as needed.
func (g *Gen) goTypeOf(s map[string]any, hint string) string {
	if s == nil {
		return "any"
	}
	if ref := refName(s); ref != "" {
		if g.skip[ref] {
			return "any"
		}
		return goName(ref)
	}
	if len(asSlice(s["allOf"])) > 0 {
		return g.queue(hint, g.mergeAllOf(s))
	}
	switch typeStr(s) {
	case "array":
		return "[]" + g.goTypeOf(asMap(s["items"]), hint+"Item")
	case "string":
		return "string"
	case "integer":
		if str(s, "format") == "uint64" {
			return "uint64"
		}
		return "int64"
	case "number":
		return "float64"
	case "boolean":
		return "bool"
	case "object", "":
		if ap, ok := s["additionalProperties"]; ok && ap != nil {
			if apm := asMap(ap); apm != nil {
				return "map[string]" + g.goTypeOf(apm, hint+"Value")
			}
			if b, ok := ap.(bool); ok && !b {
				// additionalProperties:false with no properties => empty
			}
		}
		if len(asMap(s["properties"])) > 0 {
			return g.queue(hint, s)
		}
		return "map[string]any"
	default:
		return "any"
	}
}

// ---- service emission -----------------------------------------------------

func (g *Gen) emitService(s service) string {
	var b strings.Builder
	b.WriteString(genHeader)
	b.WriteString("package flashduty\n\n")
	b.WriteString("import \"context\"\n\n")
	b.WriteString(fmt.Sprintf("// %sService handles the %q API resource.\ntype %sService service\n\n", s.Name, s.Tag, s.Name))

	for _, o := range s.Ops {
		for _, l := range o.Doc {
			if l == "" {
				b.WriteString("//\n")
			} else {
				b.WriteString("// " + l + "\n")
			}
		}
		sig, body := methodSig(s.Name, o)
		b.WriteString(sig)
		b.WriteString(body)
		b.WriteString("\n")
	}
	return b.String()
}

func methodSig(svc string, o op) (string, string) {
	recv := fmt.Sprintf("func (s *%sService) %s(ctx context.Context", svc, o.Method)
	if o.ReqGo != "" {
		recv += fmt.Sprintf(", req *%s", o.ReqGo)
	}
	call := "do"
	if o.HTTP == "GET" {
		call = "doGet"
	}
	bodyArg := "nil"
	if o.ReqGo != "" {
		bodyArg = "req"
	}
	switch {
	case o.DataGo != "":
		sig := recv + fmt.Sprintf(") (*%s, *Response, error) {\n", o.DataGo)
		body := fmt.Sprintf("\tout := new(%s)\n\tresp, err := s.client.%s(ctx, %q, %s, out)\n\tif err != nil {\n\t\treturn nil, resp, err\n\t}\n\treturn out, resp, nil\n}\n", o.DataGo, call, o.Path, bodyArg)
		return sig, body
	default:
		sig := recv + ") (*Response, error) {\n"
		body := fmt.Sprintf("\treturn s.client.%s(ctx, %q, %s, nil)\n}\n", call, o.Path, bodyArg)
		return sig, body
	}
}

// ---- wiring emission ------------------------------------------------------

func (g *Gen) emitWiring(services []service) string {
	var b strings.Builder
	b.WriteString(genHeader)
	b.WriteString("package flashduty\n\n")
	b.WriteString("// service is the shared backing for every typed service; all services view\n// the same Client through it (one allocation), mirroring google/go-github.\ntype service struct{ client *Client }\n\n")
	b.WriteString("// genServices is embedded in Client to expose the generated service handles.\ntype genServices struct {\n")
	for _, s := range services {
		b.WriteString(fmt.Sprintf("\t%s *%sService\n", s.Name, s.Name))
	}
	b.WriteString("}\n\n")
	b.WriteString("// initServices wires every service to the shared backref. Called by NewClient.\nfunc (c *Client) initServices() {\n\tc.common.client = c\n")
	for _, s := range services {
		b.WriteString(fmt.Sprintf("\tc.%s = (*%sService)(&c.common)\n", s.Name, s.Name))
	}
	b.WriteString("}\n")
	return b.String()
}

// ---- helpers --------------------------------------------------------------

func schemaOf(container map[string]any) map[string]any {
	content := asMap(container["content"])
	js := asMap(content["application/json"])
	return asMap(js["schema"])
}

func refName(s map[string]any) string {
	ref, _ := s["$ref"].(string)
	if ref == "" {
		return ""
	}
	return ref[strings.LastIndex(ref, "/")+1:]
}

func isEmptyObject(s map[string]any) bool {
	if s == nil {
		return true
	}
	if refName(s) != "" {
		return false
	}
	if len(asSlice(s["allOf"])) > 0 {
		return false
	}
	t := typeStr(s)
	if t != "" && t != "object" {
		return false
	}
	if len(asMap(s["properties"])) > 0 {
		return false
	}
	if ap, ok := s["additionalProperties"]; ok && ap != nil {
		if _, isBool := ap.(bool); !isBool {
			return false
		}
	}
	return true
}

func typeStr(s map[string]any) string {
	t, _ := s["type"].(string)
	return t
}

// isIntProp reports whether a property schema is a plain integer (used to detect
// the pagination input trio).
func isIntProp(v any) bool {
	return typeStr(asMap(v)) == "integer"
}

func asMap(v any) map[string]any {
	m, _ := v.(map[string]any)
	return m
}

func asSlice(v any) []any {
	s, _ := v.([]any)
	return s
}

func str(m map[string]any, k string) string {
	s, _ := m[k].(string)
	return s
}

func wrapText(s string) []string {
	s = strings.ReplaceAll(s, "\r", "")
	var out []string
	for _, line := range strings.Split(s, "\n") {
		out = append(out, strings.TrimRight(line, " "))
	}
	return out
}

func fileName(svc string) string {
	// CamelCase service name -> snake_case file name.
	var b strings.Builder
	for i, r := range svc {
		if r >= 'A' && r <= 'Z' {
			if i > 0 {
				b.WriteByte('_')
			}
			b.WriteRune(r - 'A' + 'a')
		} else {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func writeGo(path, src string) error {
	formatted, err := format.Source([]byte(src))
	if err != nil {
		// Write unformatted for debugging, then fail.
		_ = os.WriteFile(path, []byte(src), 0o644)
		return fmt.Errorf("format %s: %w", filepath.Base(path), err)
	}
	return os.WriteFile(path, formatted, 0o644)
}

func loadSpec(path string) (map[string]any, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var spec map[string]any
	if err := json.Unmarshal(data, &spec); err != nil {
		return nil, fmt.Errorf("parse spec: %w", err)
	}
	return spec, nil
}

func repoRoot() (string, error) {
	wd, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for dir := wd; ; {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf("go.mod not found from %s", wd)
		}
		dir = parent
	}
}
